int32_t HpaeDirectRendererManager::RegisterSessionEffectTapWriter(uint32_t sessionId,
    const std::weak_ptr<IHpaeInnerCapTapWriter> &writer)
{
    auto request = [this, sessionId, writer]() {
        auto sinkInputNode = SafeGetMap(sinkInputNodeMap_, sessionId);
        CHECK_AND_RETURN_LOG(sinkInputNode != nullptr,
            "session %{public}u not found for tap writer", sessionId);
        auto shared = writer.lock();
        CHECK_AND_RETURN_LOG(shared != nullptr, "tap writer expired, session %{public}u", sessionId);
        sinkInputNode->AddInnerCapTapWriter(shared);
        bool seAttached = sessionEffectNode_ != nullptr && sessionEffectSessionId_ == sessionId;
        if (seAttached) { sessionEffectNode_->AddTapWriter(writer); }
        AUDIO_INFO_LOG("tap writer registered, session %{public}u, se attached %{public}d", sessionId, seAttached);
    };
    SendRequest(request, __func__);
    return SUCCESS;
}

void RendererInServer::UnregisterSessionEffectTapWriterForId(int32_t innerCapId)
{
    std::shared_ptr<IHpaeInnerCapTapWriter> writer = nullptr;
    {
        std::lock_guard<std::mutex> lock(sessionEffectTapWriterMutex_);
        auto it = sessionEffectTapWriters_.find(innerCapId);
        if (it == sessionEffectTapWriters_.end()) {
            AUDIO_DEBUG_LOG("no tap writer to drop, innerCapId %{public}d", innerCapId);
            return;
        }
        writer = it->second;
        sessionEffectTapWriters_.erase(it);
    }
    uint32_t sessionId = streamIndex_;
    // Keep the writer alive until the engine request drops its last reference.
    PostSessionEffectTapWriterTask([sessionId, writer]() {
        HPAE::IHpaeManager::GetHpaeManager().UnregisterSessionEffectTapWriter(sessionId, writer);
    });
}
